<template>
  <div class="settings-category-view" data-test="settings-category-view">
    <template v-if="category">
      <div class="category-header">
        <Icon :icon="category.icon" width="40" height="40" :class="'text-' + (category.iconColor || 'primary')" />
        <div>
          <h2 class="category-title">{{ category.title }}</h2>
          <p class="category-description">{{ category.description }}</p>
        </div>
      </div>

      <div class="category-items-grid">
        <div
          v-for="item in category.items"
          :key="item.name"
          class="category-item-card"
          @click="$router.push(item.route)"
        >
          <Icon
            v-if="item.icon && item.icon.startsWith('mdi:')"
            :icon="item.icon"
            width="24"
            height="24"
            class="card-icon"
          />
          <img
            v-else-if="item.icon"
            :src="'/' + item.icon"
            class="card-icon"
            alt=""
          />
          <div class="card-info">
            <span class="card-title">{{ $t(item.translate) }}</span>
            <span class="card-desc">{{ $t(item.tooltip) }}</span>
          </div>
          <q-icon name="chevron_right" size="20px" color="grey-5" />
        </div>
      </div>
    </template>

    <div v-else class="not-found">
      <q-icon name="category" size="48px" color="grey-4" />
      <p>{{ $t('category_not_found') || 'Category not found' }}</p>
      <q-btn
        flat
        no-caps
        color="primary"
        :label="$t('back_to_settings') || 'Back to Settings'"
        @click="$router.push('/settings')"
      />
    </div>
  </div>
</template>

<script lang="ts">

import { storeToRefs } from 'pinia';
import { defineComponent } from 'vue';
import { useSettingStore } from 'src/store/main';
import type { CategoryData } from 'src/@types/settings';
import { supplier_dashboard_setting } from 'src/constants';
import { toBoolPreference } from 'src/utils/preferenceBool';
import { useSettingsNavigationStore } from 'src/store/settings-navigation';
import { isUserAdmin, isSupplierUser, getSupplierDetailsRoute } from 'src/utils/UserDetails';

export default defineComponent({
  name: 'SettingsCategoryView',
  

  setup() {
    const navStore = useSettingsNavigationStore();
    const settingStore = useSettingStore();
    const { user_settings } = storeToRefs(settingStore);
    return { navStore, user_settings };
  },

  computed: {
    categoryId(): string {
      return this.$route.params.id as string;
    },

    category(): CategoryData | undefined {
      const categories = this.navStore.getCategories(this.$t, {
        isAdmin: isUserAdmin(),
        isSupplier: isSupplierUser(),
        supplierDashboardEnabled:
          toBoolPreference(this.user_settings[supplier_dashboard_setting]),
        supplierDetailsRoute: getSupplierDetailsRoute(),
      });
      return categories.find((c) => c.id === this.categoryId);
    },
  },
});
</script>

